   212  /**
   213   * For a given cell, return its bounding box. If coverChildren is true, the bbox
   214   * will be guaranteed to contain its children at any finer resolution. Note that
   215   * no guarantee is provided as to the level of accuracy, and the bounding box
   216   * may have a significant margin of error.
   217   * @param cell Cell to calculate bbox for
   218   * @param out  BBox to hold output
   219   * @param coverChildren Whether the bounding box should cover all children
   220   */
   221  H3Error cellToBBox(H3Index cell, BBox *out, bool coverChildren) {
   222      // Adjust the BBox to handle poles, if needed
   223      int res = H3_GET_RESOLUTION(cell);
   224
   225      if (res == 0) {
   226          int baseCell = H3_GET_BASE_CELL(cell);
   227          if (NEVER(baseCell < 0) || baseCell >= NUM_BASE_CELLS) {
   228              return E_CELL_INVALID;
   229          }
   230          *out = RES0_BBOXES[baseCell];
   231      } else {
   232          LatLng center;
   233          H3Error centerErr = H3_EXPORT(cellToLatLng)(cell, &center);
   234          if (centerErr != E_SUCCESS) {
   235              return centerErr;
   236          }
   237          double lngRatio = 1 / cos(center.lat);
   238          out->north = center.lat + MAX_EDGE_LENGTH_RADS[res];
   239          out->south = center.lat - MAX_EDGE_LENGTH_RADS[res];
   240          out->east = center.lng + MAX_EDGE_LENGTH_RADS[res] * lngRatio;
   241          out->west = center.lng - MAX_EDGE_LENGTH_RADS[res] * lngRatio;
   242      }
   243
   244      // Buffer the bounding box to cover children. Call this even if no buffering
   245      // is required in order to normalize the bbox to lat/lng bounds
   246      scaleBBox(out, coverChildren ? CHILD_SCALE_FACTOR : CELL_SCALE_FACTOR);
   247
   248      // Cell that contains the north pole
   249      if (cell == NORTH_POLE_CELLS[res]) {
   250          out->north = M_PI_2;
