   696  H3Error H3_EXPORT(polygonToCellsExperimental)(const GeoPolygon *polygon,
   697                                                int res, uint32_t flags,
   698                                                H3Index *out) {
   699  #ifdef H3_POLYGON_TO_CELLS_ASSERT
   700      // TODO: This is incompatible with testH3Memory, since it will make more
   701      // allocations. This is just for debugging that the algorithm is not
   702      // exceeding its buffer size.
   703      int64_t maxSize;
   704      H3Error sizeError = H3_EXPORT(maxPolygonToCellsSizeExperimental)(
   705          polygon, res, flags, &maxSize);
   706      if (sizeError) {
   707          return sizeError;
   708      }
   709  #endif
   710
   711      IterCellsPolygon iter = iterInitPolygon(polygon, res, flags);
   712      int64_t i = 0;
   713      for (; iter.cell; iterStepPolygon(&iter)) {
   714  #ifdef H3_POLYGON_TO_CELLS_ASSERT
   715          if (NEVER(i >= maxSize)) {
   716              iterDestroyPolygon(&iter);
   717              return E_FAILED;
   718          }
   719  #endif
   720          out[i++] = iter.cell;
   721      }
   722      return iter.error;
   723  }
