   733  /**
   734   * maxPolygonToCellsSize returns the number of cells to allocate space for
   735   * when performing a polygonToCells on the given GeoJSON-like data structure.
   736   * @param geoPolygon A GeoJSON-like data structure indicating the poly to fill
   737   * @param res Hexagon resolution (0-15)
   738   * @param out number of cells to allocate for
   739   * @return 0 (E_SUCCESS) on success.
   740   */
   741  H3Error H3_EXPORT(maxPolygonToCellsSizeExperimental)(const GeoPolygon *polygon,
   742                                                       int res, uint32_t flags,
   743                                                       int64_t *out) {
   744      // Special case: 0-vertex polygon
   745      if (polygon->geoloop.numVerts == 0) {
   746          *out = 0;
   747          return E_SUCCESS;
   748      }
   749
   750      // Initialize the iterator without stepping, so we can adjust the res and
   751      // flags (after they are validated by the initialization) before we start
   752      IterCellsPolygonCompact iter = _iterInitPolygonCompact(polygon, res, flags);
   753
   754      if (iter.error) {
   755          return iter.error;
   756      }
   757
   758      // Ignore the requested flags and use the faster overlapping-bbox mode
   759      iter._flags = CONTAINMENT_OVERLAPPING_BBOX;
   760
   761      // Get a (very) rough area of the polygon bounding box
   762      BBox *polygonBBox = &iter._bboxes[0];
   763      double polygonBBoxAreaKm2 =
   764          bboxHeightRads(polygonBBox) * bboxWidthRads(polygonBBox) /
   765          cos(fmin(fabs(polygonBBox->north), fabs(polygonBBox->south))) *
   766          EARTH_RADIUS_KM * EARTH_RADIUS_KM;
   767
   768      // Determine the res for the size estimate, based on a (very) rough estimate
   769      // of the number of cells at various resolutions that would fit in the
   770      // polygon. All we need here is a general order of magnitude.
   771      while (iter._res > 0 &&
   772             polygonBBoxAreaKm2 / getAverageCellArea(iter._res - 1) >
   773                 MAX_SIZE_CELL_THRESHOLD) {
   774          iter._res--;
   775      }
   776
   777      // Now run the polyfill, counting the output in the target res.
   778      // We have to take the first step outside the loop, to get the first
   779      // valid output cell
   780      iterStepPolygonCompact(&iter);
