    39  int populateGeoLoop(GeoLoop *g, const uint8_t *data, size_t *offset,
    40                      size_t size) {
    41      if (size < *offset + sizeof(int)) {
    42          return 1;
    43      }
    44      int numVerts = *(const int *)(data + *offset);
    45      *offset = *offset + sizeof(int);
    46      g->numVerts = numVerts;
    47      if (size < *offset + sizeof(LatLng) * numVerts) {
    48          return 1;
    49      }
    50      g->verts = (LatLng *)(data + *offset);
    51      *offset = *offset + sizeof(LatLng) * numVerts;
    52      return 0;
    53  }
