    55  void run(GeoPolygon *geoPolygon, uint32_t flags, int res) {
    56      int64_t sz;
    57      H3Error err = H3_EXPORT(maxPolygonToCellsSizeExperimental)(geoPolygon, res,
    58                                                                 flags, &sz);
    59      if (!err && sz < MAX_SZ) {
    60          H3Index *out = calloc(sz, sizeof(H3Index));
    61          H3_EXPORT(polygonToCellsExperimental)(geoPolygon, res, flags, out);
    62          free(out);
    63      }
    64  }
