    66  int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    67      // TODO: It is difficult for the fuzzer to generate inputs that are
    68      // considered valid by this fuzzer. fuzzerPolygonToCellsNoHoles.c
    69      // is a workaround for that.
    70      if (size < sizeof(inputArgs)) {
    71          return 0;
    72      }
    73      const inputArgs *args = (const inputArgs *)data;
    74      int res = args->res % (MAX_RES + 1);
    75
    76      GeoPolygon geoPolygon;
    77      int originalNumHoles = args->numHoles % MAX_HOLES;
    78      geoPolygon.numHoles = originalNumHoles;
    79      if (geoPolygon.numHoles < 0) {
    80          return 0;
    81      }
    82      geoPolygon.holes = calloc(geoPolygon.numHoles, sizeof(GeoLoop));
    83      size_t offset = sizeof(inputArgs) - sizeof(args->buffer);
    84      if (populateGeoLoop(&geoPolygon.geoloop, data, &offset, size)) {
    85          free(geoPolygon.holes);
    86          return 0;
    87      }
    88      for (int i = 0; i < geoPolygon.numHoles; i++) {
    89          if (populateGeoLoop(&geoPolygon.holes[i], data, &offset, size)) {
    90              free(geoPolygon.holes);
    91              return 0;
    92          }
    93      }
    94
    95      for (uint32_t flags = 0; flags < CONTAINMENT_INVALID; flags++) {
    96          geoPolygon.numHoles = originalNumHoles;
    97          run(&geoPolygon, flags, res);
    98          geoPolygon.numHoles = 0;
    99          run(&geoPolygon, flags, res);
   100      }
   101      free(geoPolygon.holes);
   102
   103      return 0;
   104  }
